WITH filtered_customers AS (SELECT * FROM customers WHERE YEAR(signup_date) >= 2025 AND is_active), summary AS (SELECT segment, MONTH(signup_date) AS signup_month, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(city))) AS city_values, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(country))) AS country_values FROM filtered_customers GROUP BY segment, MONTH(signup_date)) SELECT segment, signup_month, country_values FROM summary ORDER BY 1
